from pathlib import Path
import base64
out=Path(__file__).resolve().parents[1]/'public/images'
poster=base64.b64encode((out/'ferrari-poster.webp').read_bytes()).decode()
def svg(body,bg='#111715'):
 return f'<svg xmlns="http://www.w3.org/2000/svg" width="900" height="650" viewBox="0 0 900 650"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="{bg}"/><stop offset="1" stop-color="#030705"/></linearGradient><linearGradient id="shade"><stop stop-color="#030806"/><stop offset="1" stop-color="#03080600"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="30" stdDeviation="25" flood-opacity=".45"/></filter></defs><rect width="900" height="650" fill="url(#bg)"/>{body}</svg>'
veloce=f'''<circle cx="670" cy="190" r="220" fill="#294235" opacity=".25"/><g transform="translate(64 94) rotate(-5 390 245)" filter="url(#shadow)"><rect width="780" height="460" rx="12" fill="#080e0b" stroke="#6d8274" stroke-opacity=".4"/><image href="data:image/webp;base64,{poster}" x="0" y="45" width="780" height="414" preserveAspectRatio="xMidYMid slice"/><rect y="45" width="780" height="414" fill="url(#shade)"/><text x="30" y="29" fill="#e9f4ed" font-family="Arial" font-weight="bold" font-size="14" letter-spacing="3">VELOCE</text><text x="452" y="28" fill="#a7b9ae" font-family="Arial" font-size="9">Coleção     Experiência     Sobre</text><rect x="665" y="14" width="90" height="23" rx="3" fill="#c7e8ca"/><text x="682" y="29" font-family="Arial" font-size="8" fill="#17351d">Agende sua visita</text><text x="40" y="161" fill="#c5dabd" font-family="Arial" font-size="8" letter-spacing="3">A ARTE DE IR ALÉM</text><text x="38" y="218" fill="#fff" font-family="Arial" font-size="47" font-weight="bold">Driven by</text><text x="38" y="267" fill="#c5dabd" font-family="Arial" font-size="47" font-weight="bold">extraordinary.</text><text x="40" y="300" fill="#c5cec8" font-family="Arial" font-size="10">Uma nova perspectiva de performance e sofisticação.</text><rect x="40" y="329" width="127" height="34" rx="3" fill="#c5dabd"/><text x="59" y="350" fill="#17351d" font-family="Arial" font-size="9">Explore a coleção ↗</text><text x="40" y="428" fill="#b8ccbe" font-family="Arial" font-size="8" letter-spacing="2">CONCEITO VISUAL / SEM CLIENTE ASSOCIADO</text></g>'''
(out/'project-veloce.svg').write_text(svg(veloce,'#1b2d22'))
orbit='''<circle cx="480" cy="300" r="245" fill="#5b536e" opacity=".15"/><g transform="translate(65 85) rotate(4 385 240)" filter="url(#shadow)"><rect width="770" height="480" rx="12" fill="#f2f0eb"/><path d="M12 0h158v480H12a12 12 0 0 1-12-12V12A12 12 0 0 1 12 0" fill="#dedbd4"/><text x="27" y="48" font-family="Arial" font-size="23" font-weight="bold" fill="#242b26">◉ orbit</text><text x="25" y="105" font-family="Arial" font-size="9" fill="#73766b">WORKSPACE</text><rect x="15" y="126" width="140" height="34" rx="6" fill="#ccc9be"/><text x="29" y="148" font-family="Arial" font-size="11" fill="#26362b">Visão geral</text><text x="29" y="188" font-family="Arial" font-size="11" fill="#73766b">Meus projetos</text><text x="29" y="227" font-family="Arial" font-size="11" fill="#73766b">Calendário</text><text x="29" y="266" font-family="Arial" font-size="11" fill="#73766b">Arquivos</text><text x="202" y="49" font-family="Arial" font-size="9" fill="#778275">SEU ESPAÇO PARA CRIAR</text><text x="200" y="87" font-family="Arial" font-size="28" fill="#202c24" font-weight="bold">Faça espaço para o que importa.</text><text x="202" y="112" font-family="Arial" font-size="10" fill="#7b8277">Suas ideias, conectadas. Seu trabalho, em movimento.</text><rect x="202" y="143" width="535" height="104" rx="9" fill="#243a2d"/><text x="223" y="171" fill="#b3c9af" font-family="Arial" font-size="9">EM FOCO HOJE</text><text x="223" y="202" fill="#fff" font-family="Arial" font-size="20">Brand experience</text><text x="223" y="225" fill="#a4b7a6" font-family="Arial" font-size="10">Organize as próximas etapas da sua ideia.</text><circle cx="690" cy="195" r="24" fill="#91b18c"/><text x="682" y="201" font-family="Arial" font-size="20" fill="#213a29">↗</text>'''
for i,(title,label,color) in enumerate([('Planejar','Definição de escopo','#ece8e0'),('Criar','Exploração visual','#e7e4ee'),('Evoluir','Próximos passos','#dce5d8')]):
 x=202+i*182
